$start=function(string $op,array $values=[],string $version='',bool $upload=false)use($websiteTab,$nativeId,$nativePostedFields,&$restoreNative){
 $restoreNative=input($_POST,'action')==='website-native'&&input($_POST,'operation')===$op;
 // Match the exact edited object, including individual images and social events.
 foreach(['id','event_id','field','filename'] as $identity)if(array_key_exists($identity,$values)&&input($nativePostedFields,$identity)!==(string)$values[$identity])$restoreNative=false;
 if($restoreNative)$version=input($_POST,'version');
 echo '<form method="post" class="native-form"'.($upload?' enctype="multipart/form-data"':'').'>'.csrf().hidden('action','website-native').hidden('operation',$op).hidden('return_tab',$websiteTab).hidden('return_item',(string)$nativeId).hidden('version',$version).hidden('request_key',$restoreNative?input($_POST,'request_key'):bin2hex(random_bytes(16)));
 foreach($values as $key=>$value)echo hidden('fields['.$key.']',(string)$value);
};
$field=function(string $key,string $label,mixed $value='',string $type='text',bool $required=false)use($nativePostedFields,&$restoreNative){if($restoreNative&&$type!=='password'&&is_string($nativePostedFields[$key]??null))$value=$nativePostedFields[$key];echo '<label>'.e($label);if($type==='textarea'||$type==='rich')echo '<textarea class="form-control" name="fields['.e($key).']" rows="'.($type==='rich'?'12':'3').'"'.($type==='rich'?' data-native-rich':'').'>'.e((string)$value).'</textarea>';else echo '<input class="form-control" name="fields['.e($key).']" type="'.e($type).'" value="'.e((string)$value).'"'.($required?' required':'').'>';echo '</label>';};
$check=function(string $key,string $label,bool $checked=false)use($nativePostedFields,&$restoreNative){if($restoreNative)$checked=($nativePostedFields[$key]??'')==='1';echo '<label class="check"><input class="check" type="checkbox" name="fields['.e($key).']" value="1"'.($checked?' checked':'').'>'.e($label).'</label>';};
$nativeCanWrite=$website->canWrite($websiteTab);
$button=function(string $label,bool $enabled=true)use($nativeCanWrite){$enabled=$enabled&&$nativeCanWrite;echo '<button class="btn btn-solid theme-primary"'.($enabled?'':' disabled title="Auf diesem PC gesperrt"').'>'.e($label).'</button></form>';};
$simple=function(string $op,string $label,array $values=[],string $version='',bool $enabled=true)use($start,$button){$start($op,$values,$version);$button($label,$enabled);};
